function validate(input) {
  const [{ animals = [] }] = input;
  const weights = new Set();
  for (const [, , age, weight] of animals) {
    if (age === null || weight === null) return 'age and weight cannot be null.';
    if (age < 0 || weight < 0) return 'age and weight cannot be negative.';
    if (weights.has(weight)) return `Two animals weigh ${weight}; weights must be distinct.`;
    weights.add(weight);
  }
  return null;
}

