function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Tatiana', 'Khaled', 'Alex', 'Jonathan', 'Stefan', 'Tommy', 'Rex'];
  const species = ['Snake', 'Giraffe', 'Leopard', 'Monkey', 'Bear', 'Panda'];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  // Small cases draw weights near the 100 boundary; large ones from a wide range. Weights stay distinct.
  const pool = [];
  if (size === 'small') for (const w of [0, 41, 50, 99, 100, 101, 102, 328, 349, 463, 464, 500]) pool.push(w);
  else for (let w = 0; w <= 6000; w++) pool.push(w);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const animals = [];
  for (let i = 0; i < count; i++) animals.push([pick(names), pick(species), Math.floor(rand() * 101), pool[i]]);
  return [{ animals }];
}
